sessions_privacy_hashes_check.value:
("sessions"."oidc_session_id_hash" is null or (
          length("sessions"."oidc_session_id_hash") = 22
          and "sessions"."oidc_session_id_hash" not glob '*[^A-Za-z0-9_-]*'
        )) and ("sessions"."ip_hash" is null or (
          length("sessions"."ip_hash") = 22
          and "sessions"."ip_hash" not glob '*[^A-Za-z0-9_-]*'
        )) and ("sessions"."user_agent_hash" is null or (
          length("sessions"."user_agent_hash") = 22
          and "sessions"."user_agent_hash" not glob '*[^A-Za-z0-9_-]*'
        ))
